\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{booktabs}
\usepackage{colortbl}
\pagestyle{empty}

% ── Dark Tech Color Palette ──
\definecolor{primary}{HTML}{0A0F2E}        % deep navy (title bar, darkest)
\definecolor{secondary}{HTML}{1E3A8A}      % electric blue (section headers)
\definecolor{accent}{HTML}{06B6D4}         % teal/cyan (highlights)
\definecolor{amber}{HTML}{F59E0B}          % warm amber (callouts)
\definecolor{bgposter}{HTML}{0D1117}       % near-black background
\definecolor{bgcard}{HTML}{161B2E}         % dark card background
\definecolor{bgcardalt}{HTML}{0F1729}      % alternate dark card
\definecolor{bgteal}{HTML}{0A2535}         % teal-tinted dark card
\definecolor{bgamber}{HTML}{1F1706}        % amber-tinted dark card
\definecolor{textlight}{HTML}{E2E8F0}      % main text on dark
\definecolor{textmid}{HTML}{94A3B8}        % muted text
\definecolor{textbright}{HTML}{F8FAFC}     % bright white-ish
\definecolor{statbg}{HTML}{1E2A4A}         % stat callout bg
\definecolor{openai}{HTML}{10A37F}         % OpenAI green
\definecolor{anthropic}{HTML}{CC785C}      % Anthropic warm orange
\definecolor{google}{HTML}{4285F4}         % Google blue
\definecolor{deepseek}{HTML}{7C3AED}       % DeepSeek purple
\definecolor{openairank}{HTML}{0D2E26}     % OpenAI row tint
\definecolor{anthropicrank}{HTML}{2E1A14}  % Anthropic row tint
\definecolor{googlerank}{HTML}{0D1E3E}     % Google row tint
\definecolor{deepseekrank}{HTML}{1A0F2E}   % DeepSeek row tint
\definecolor{gridline}{HTML}{1E3A5F}       % subtle grid line

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{accent}$\bullet$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{amber}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=bgcard, colframe=bgcard,
    borderline west={4pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bgcardalt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={secondary!60},
    valign=top,
  },
  tealcard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=bgteal, colframe=bgteal,
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bgposter,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={accent!40},
    valign=top,
  },
  ambercard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=bgamber, colframe=bgamber,
    borderline west={4pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=bgposter,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={amber!40},
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=secondary, colframe=secondary,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textbright},
    coltitle=textbright, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top,
  },
}

% ── Horizontal bar macro ──
% #1 = fraction 0-1, #2 = color, #3 = width in \linewidth fraction
\newcommand{\hbar}[2]{%
  \noindent\begin{tikzpicture}[baseline=-0.5ex]
    \fill[bgcard!60] (0,0) rectangle (0.92\linewidth,10pt);
    \fill[#2] (0,0) rectangle (#1 * 0.92\linewidth,10pt);
  \end{tikzpicture}%
}

% ── Inline bar chart row macro ──
% #1=rank, #2=model, #3=family-color, #4=pct-value (0.0-1.0), #5=pct-label, #6=cost
\newcommand{\modelrow}[6]{%
  {\fontsize{26}{32}\selectfont%
  \textcolor{textmid}{\##1}\quad
  \textcolor{#3}{\textbf{#2}}\hfill\textcolor{textbright}{\textbf{#5}}\quad\textcolor{textmid}{\$#6}}\\[2pt]
  \noindent\begin{tikzpicture}[baseline=0]
    \fill[bgcard!80] (0,0) rectangle (0.96\linewidth,8pt);
    \fill[#3!80!white] (0,0) rectangle (#4 * 0.96\linewidth,8pt);
  \end{tikzpicture}\\[6pt]
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════
% TITLE BAR (rows 1-3)
% ══════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{secondary},
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{68}{82}\selectfont\bfseries\color{textbright}%
    Aider LLM Polyglot Coding Leaderboard 2025}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{accent}%
    Ranking top LLMs on autonomous code editing across \textbf{6 languages} \& \textbf{225 exercises}}\\[8pt]
  {\fontsize{26}{34}\selectfont\color{textmid}%
    Source: aider.chat/docs/leaderboards \quad|\quad Models benchmarked: OpenAI · Anthropic · Google · DeepSeek}
}

% ══════════════════════════════════════
% STAT BANNER (rows 3-5)
% ══════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, colframe=statbg,
  arc=0pt, boxrule=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{secondary!50},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \tcbox[enhanced, colback=primary, colframe=secondary, arc=4pt, boxrule=1.5pt,
      left=6pt, right=6pt, top=4pt, bottom=4pt]{%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} 88.0\%}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{amber}\textbf{Top Score}}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textmid} GPT-5 (high)}%
    }
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \tcbox[enhanced, colback=primary, colframe=secondary, arc=4pt, boxrule=1.5pt,
      left=6pt, right=6pt, top=4pt, bottom=4pt]{%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} 225}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{amber}\textbf{Exercises}}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textmid} Exercism challenges}%
    }
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \tcbox[enhanced, colback=primary, colframe=secondary, arc=4pt, boxrule=1.5pt,
      left=6pt, right=6pt, top=4pt, bottom=4pt]{%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} 6}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{amber}\textbf{Languages}}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textmid} C++ Go Java JS Py Rust}%
    }
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \tcbox[enhanced, colback=primary, colframe=secondary, arc=4pt, boxrule=1.5pt,
      left=6pt, right=6pt, top=4pt, bottom=4pt]{%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} 23$\times$}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{amber}\textbf{Cost Range}}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textmid} \$1.28 to \$29.08 per run}%
    }
  \end{minipage}
}

% ══════════════════════════════════════
% COL 1: TOP MODELS RANKED (rows 5-17)
% ══════════════════════════════════════
\posterbox[darkcard, title={Top 15 Models by Accuracy}
]{name=ranking, column=1, between=row5 and row17}{
  \fontsize{26}{34}\selectfont
  % Legend
  \noindent
  \textcolor{openai}{$\blacksquare$}\,\textcolor{textmid}{OpenAI}\quad
  \textcolor{anthropic}{$\blacksquare$}\,\textcolor{textmid}{Anthropic}\quad
  \textcolor{google}{$\blacksquare$}\,\textcolor{textmid}{Google}\quad
  \textcolor{deepseek}{$\blacksquare$}\,\textcolor{textmid}{DeepSeek}\\[10pt]

  \modelrow{1}{GPT-5 (high)}{openai}{0.880}{88.0\%}{29.08}
  \modelrow{2}{GPT-5 (medium)}{openai}{0.867}{86.7\%}{17.69}
  \modelrow{3}{Claude 4.0 Opus}{anthropic}{0.853}{85.3\%}{22.14}
  \modelrow{4}{Claude 4.0 Sonnet}{anthropic}{0.840}{84.0\%}{9.47}
  \modelrow{5}{Gemini 2.5 Pro}{google}{0.827}{82.7\%}{4.92}
  \modelrow{6}{o3 (high)}{openai}{0.822}{82.2\%}{18.35}
  \modelrow{7}{GPT-5 (low)}{openai}{0.813}{81.3\%}{8.12}
  \modelrow{8}{DeepSeek R1-0528}{deepseek}{0.804}{80.4\%}{3.88}
  \modelrow{9}{Claude 3.7 Sonnet}{anthropic}{0.796}{79.6\%}{7.81}
  \modelrow{10}{o3 (medium)}{openai}{0.787}{78.7\%}{10.22}
  \modelrow{11}{Gemini 2.5 Flash}{google}{0.764}{76.4\%}{1.28}
  \modelrow{12}{GPT-4.1}{openai}{0.747}{74.7\%}{5.60}
  \modelrow{13}{DeepSeek V3-0324}{deepseek}{0.729}{72.9\%}{1.95}
  \modelrow{14}{Claude 3.5 Sonnet}{anthropic}{0.720}{72.0\%}{6.33}
  \modelrow{15}{o4-mini (high)}{openai}{0.711}{71.1\%}{4.47}
}

% ══════════════════════════════════════
% COL 1 BOTTOM: ABOUT BENCHMARK (rows 17-20)
% ══════════════════════════════════════
\posterbox[tealcard, title={About the Benchmark}
]{name=about, column=1, between=row17 and bottom}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}
    \item \textbf{225 Exercism exercises}, 2 attempts per problem
    \item Languages: C++, Go, Java, JS, Python, Rust
    \item Metric: \% exercises where all tests pass
    \item No human intervention — fully automated runs
    \item Also tracks edit format compliance \& cost
  \end{itemize}
}

% ══════════════════════════════════════
% COL 2: COST vs ACCURACY (rows 5-13)
% ══════════════════════════════════════
\posterbox[ambercard, title={Cost vs.\ Accuracy Trade-Off}
]{name=costplot, column=2, between=row5 and row13}{
  \fontsize{26}{34}\selectfont
  % Bubble chart via TikZ
  \begin{center}
  \begin{tikzpicture}[x=0.026\linewidth, y=0.9pt]
    % Background grid
    \fill[bgcard] (-1,-50) rectangle (31,900);
    % Grid lines
    \foreach \y in {700,720,740,760,780,800,820,840,860,880}{
      \draw[gridline!60, very thin] (-0.5,\y) -- (30.5,\y);
    }
    \foreach \x in {0,5,10,15,20,25,30}{
      \draw[gridline!60, very thin] (\x,690) -- (\x,895);
    }
    % Axis labels
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (0,690) {0};
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (5,690) {\$5};
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (10,690) {\$10};
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (15,690) {\$15};
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (20,690) {\$20};
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (25,690) {\$25};
    \node[anchor=north, color=textmid, font=\fontsize{20}{24}\selectfont] at (30,690) {\$29};
    % Y-axis labels (accuracy %)
    \node[anchor=east, color=textmid, font=\fontsize{20}{24}\selectfont] at (-1,711) {71\%};
    \node[anchor=east, color=textmid, font=\fontsize{20}{24}\selectfont] at (-1,760) {76\%};
    \node[anchor=east, color=textmid, font=\fontsize{20}{24}\selectfont] at (-1,800) {80\%};
    \node[anchor=east, color=textmid, font=\fontsize{20}{24}\selectfont] at (-1,853) {85\%};
    \node[anchor=east, color=textmid, font=\fontsize{20}{24}\selectfont] at (-1,880) {88\%};
    % Axis title
    \node[color=textmid, font=\fontsize{20}{24}\selectfont, anchor=south] at (15,896) {Cost per run (USD)};
    % ── Data points (cost, accuracy*10, label) ──
    % OpenAI
    \filldraw[openai] (29.08, 880) circle (7pt);
    \node[anchor=west, color=openai, font=\fontsize{19}{22}\selectfont] at (29.3,880) {GPT-5h};
    \filldraw[openai] (17.69, 867) circle (6pt);
    \node[anchor=west, color=openai, font=\fontsize{19}{22}\selectfont] at (17.9,862) {GPT-5m};
    \filldraw[openai] (18.35, 822) circle (6pt);
    \node[anchor=east, color=openai, font=\fontsize{19}{22}\selectfont] at (18.1,817) {o3h};
    \filldraw[openai] (8.12, 813) circle (6pt);
    \node[anchor=west, color=openai, font=\fontsize{19}{22}\selectfont] at (8.3,808) {GPT-5l};
    \filldraw[openai] (10.22, 787) circle (5pt);
    \node[anchor=west, color=openai, font=\fontsize{19}{22}\selectfont] at (10.4,782) {o3m};
    \filldraw[openai] (5.60, 747) circle (5pt);
    \node[anchor=west, color=openai, font=\fontsize{19}{22}\selectfont] at (5.8,742) {GPT-4.1};
    \filldraw[openai] (4.47, 711) circle (5pt);
    \node[anchor=west, color=openai, font=\fontsize{19}{22}\selectfont] at (4.6,706) {o4m};
    % Anthropic
    \filldraw[anthropic] (22.14, 853) circle (6pt);
    \node[anchor=west, color=anthropic, font=\fontsize{19}{22}\selectfont] at (22.3,853) {Cl4O};
    \filldraw[anthropic] (9.47, 840) circle (6pt);
    \node[anchor=east, color=anthropic, font=\fontsize{19}{22}\selectfont] at (9.3,835) {Cl4S};
    \filldraw[anthropic] (7.81, 796) circle (5pt);
    \node[anchor=east, color=anthropic, font=\fontsize{19}{22}\selectfont] at (7.6,791) {Cl3.7S};
    \filldraw[anthropic] (6.33, 720) circle (5pt);
    \node[anchor=west, color=anthropic, font=\fontsize{19}{22}\selectfont] at (6.5,715) {Cl3.5S};
    % Google
    \filldraw[google] (4.92, 827) circle (6pt);
    \node[anchor=west, color=google, font=\fontsize{19}{22}\selectfont] at (5.1,822) {G2.5P};
    \filldraw[google] (1.28, 764) circle (6pt);
    \node[anchor=west, color=google, font=\fontsize{19}{22}\selectfont] at (1.5,759) {G2.5F};
    % DeepSeek
    \filldraw[deepseek] (3.88, 804) circle (6pt);
    \node[anchor=west, color=deepseek, font=\fontsize{19}{22}\selectfont] at (4.1,799) {DS-R1};
    \filldraw[deepseek] (1.95, 729) circle (5pt);
    \node[anchor=west, color=deepseek, font=\fontsize{19}{22}\selectfont] at (2.1,724) {DS-V3};
    % Value frontier annotation
    \draw[accent, dashed, thick] (1.28,764) -- (3.88,804) -- (4.92,827) -- (9.47,840) -- (22.14,853) -- (29.08,880);
    \node[color=accent, font=\fontsize{18}{22}\selectfont, anchor=north west] at (2,830) {value frontier};
  \end{tikzpicture}
  \end{center}
  \vspace{2pt}
  {\fontsize{23}{30}\selectfont\color{textmid}
  Each point = 1 model. X = cost/run, Y = accuracy. Dashed = value frontier.}
}

% ══════════════════════════════════════
% COL 2: EDIT FORMAT COMPLIANCE (rows 13-17)
% ══════════════════════════════════════
\posterbox[tealcard, title={Edit Format Compliance}
]{name=editfmt, column=2, between=row13 and row17}{
  \fontsize{26}{34}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \noindent\begin{tabular}{@{}p{0.44\linewidth}@{\hspace{4pt}}p{0.18\linewidth}@{\hspace{4pt}}p{0.28\linewidth}@{}}
    \rowcolor{bgcard}
    {\color{accent}\textbf{Model}} & {\color{accent}\textbf{Format}} & {\color{accent}\textbf{Compliance}} \\
    \rowcolor{bgcardalt}
    \textcolor{anthropic}{Claude 4.0 Opus}    & diff-fenced & \textcolor{openai}{\textbf{97.3\%}} \\
    \rowcolor{bgcard}
