\definecolor{accent}{HTML}{00D4FF}         % cyan highlight
\definecolor{amber}{HTML}{FFB020}          % warm amber
\definecolor{bgposter}{HTML}{080C1A}       % near-black background
\definecolor{bgcard}{HTML}{10162B}         % dark card background
\definecolor{bgcardalt}{HTML}{0C1222}      % alternate dark card
\definecolor{bgteal}{HTML}{061820}         % teal-tinted dark card
\definecolor{bgamber}{HTML}{1A1004}        % amber-tinted dark card
\definecolor{textlight}{HTML}{DCE8F5}      % main text on dark
\definecolor{textmid}{HTML}{7A9BB8}        % muted text
\definecolor{textbright}{HTML}{F0F8FF}     % bright white-ish
\definecolor{statbg}{HTML}{0D1A3A}         % stat callout bg
\definecolor{openai}{HTML}{10D890}         % OpenAI green
\definecolor{anthropic}{HTML}{E08060}      % Anthropic warm orange
\definecolor{google}{HTML}{5B9CF6}         % Google blue
\definecolor{deepseek}{HTML}{A78BFA}       % DeepSeek purple
\definecolor{gridline}{HTML}{1A3060}       % subtle grid line

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{accent}\textbf{>}}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{amber}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=2pt, boxrule=0pt,
    colback=bgcard, colframe=bgcard,
    borderline west={4pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bgcardalt,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={secondary!80},
    valign=top,
  },
  tealcard/.style={
    enhanced, arc=2pt, boxrule=0pt,
