    borderline west={4pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=bgposter,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=1pt, titlerule style={amber!50},
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=2pt, boxrule=0pt,
    colback=secondary, colframe=secondary,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=6pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{textbright},
    coltitle=textbright, colbacktitle=primary,
    toptitle=4pt, bottomtitle=4pt,
    valign=top,
  },
}

% ── Model row: rank label + accuracy bar ──
% #1=rank, #2=label, #3=color, #4=bar fraction, #5=pct text, #6=cost
\newcommand{\modelrow}[6]{%
  {\fontsize{24}{30}\selectfont\color{textmid}\##1\quad
   \textcolor{#3}{\textbf{#2}}\hfill
   \textcolor{textbright}{\textbf{#5}}\enspace\textcolor{textmid}{\$#6}}\\[1pt]
  \noindent\begin{tikzpicture}
    \fill[bgcardalt] (0,0) rectangle (0.94\linewidth, 7pt);
    \fill[#3] (0,0) rectangle (#4\dimexpr0.94\linewidth, 7pt);
  \end{tikzpicture}\\[5pt]
}

